/** Change vs. the previous weekly reading, derived rather than stored. */
export const weekDelta = (p: Patient) =>
  p.healthHistory[p.healthHistory.length - 1]! - p.healthHistory[p.healthHistory.length - 2]!;

/** Change over the trailing four weeks. */
export const fourWeekDelta = (p: Patient) =>
  p.healthHistory[p.healthHistory.length - 1]! - p.healthHistory[p.healthHistory.length - 5]!;

/** Peak index within the 13-week window minus the current value. */
export const drawdown = (p: Patient) =>
  Math.max(...p.healthHistory) - p.healthScore;

/** Index as of four weeks ago, for stat-row deltas. */
export const indexFourWeeksAgo = (p: Patient) =>
  p.healthHistory[p.healthHistory.length - 5]!;

/** Severe, disabling menstrual pain (driver at the bottom of its range). */
export const hasSeverePain = (p: Patient) =>
  (p.drivers.find((d) => d.key === "dor")?.points ?? 0) <= -12;
